import{_ as t,o as e,c as s,a6 as r}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"一次请求的旅程","description":"用户在地址栏敲下回车到页面渲染，中间经过 DNS、CDN、负载均衡、Nginx、应用、数据库六道关卡——每一道都能被做手脚。这一章画出完整攻击面地图，后面每一章各拆一段。","frontmatter":{"title":"一次请求的旅程","description":"用户在地址栏敲下回车到页面渲染，中间经过 DNS、CDN、负载均衡、Nginx、应用、数据库六道关卡——每一道都能被做手脚。这一章画出完整攻击面地图，后面每一章各拆一段。","source":"https://daiw.org/manual/web-security/request-journey"},"headers":[],"relativePath":"manual/computer-programming/web-security/request-journey.md","filePath":"manual/computer-programming/web-security/request-journey.md"}'),n={name:"manual/computer-programming/web-security/request-journey.md"};function i(l,a,o,p,d,h){return e(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="一次请求的旅程" tabindex="-1">一次请求的旅程 <a class="header-anchor" href="#一次请求的旅程" aria-label="Permalink to &quot;一次请求的旅程&quot;">​</a></h1><p>用户在地址栏敲下回车到页面渲染，中间经过 DNS、CDN、负载均衡、Nginx、应用、数据库六道关卡——每一道都能被做手脚。这一章画出完整攻击面地图，后面每一章各拆一段。</p><p>跟着一次 <code>https://example.com/profile</code> 走完全程。<strong>每一站都标出「这里能被做什么手脚」</strong>，这就是你的攻击面地图。</p><h2 id="全程六站" tabindex="-1">全程六站 <a class="header-anchor" href="#全程六站" aria-label="Permalink to &quot;全程六站&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  U[浏览器] --&gt;|① DNS 解析| D[(DNS)]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  U --&gt;|② TLS 握手| E[CDN / ALB 边缘]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E --&gt;|③ 回源| N[Nginx]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  N --&gt;|④ 反代| A[应用]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A --&gt;|⑤ 查询| DB[(数据库)]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A --&gt;|⑥ 外呼| X[第三方 API]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="_1-dns-解析-还没连上就可能被劫持" tabindex="-1">① DNS 解析：还没连上就可能被劫持 <a class="header-anchor" href="#_1-dns-解析-还没连上就可能被劫持" aria-label="Permalink to &quot;① DNS 解析：还没连上就可能被劫持&quot;">​</a></h2><p>浏览器先问「example.com 的 IP 是多少」。这一步出问题，<strong>后面全部作废</strong>——用户连的根本不是你的服务器。</p><table tabindex="0"><thead><tr><th>手法</th><th>怎么发生</th></tr></thead><tbody><tr><td>注册商账号被撞</td><td>攻击者登录你的域名后台，直接改 NS 记录</td></tr><tr><td>DNS 投毒</td><td>污染递归解析器缓存，返回假 IP</td></tr><tr><td>子域名接管</td><td><code>blog.example.com</code> 的 CNAME 指向一个你已删除的云服务，攻击者去把那个名字注册回来</td></tr></tbody></table><p><strong>这一站的可怕之处在于：你的服务器日志里什么都看不到。</strong> 流量根本没到你这儿。</p><p>对应章节：<a href="/Front2Full/manual/computer-programming/web-security/registrar-security">注册商</a>、<a href="/Front2Full/manual/computer-programming/web-security/dns-hardening">DNS 加固</a>、<a href="/Front2Full/manual/computer-programming/web-security/subdomain-takeover">子域名接管</a>。</p><h2 id="_2-tls-握手-证书是谁签的" tabindex="-1">② TLS 握手：证书是谁签的 <a class="header-anchor" href="#_2-tls-握手-证书是谁签的" aria-label="Permalink to &quot;② TLS 握手：证书是谁签的&quot;">​</a></h2><p>拿到 IP 后建立 TLS 连接。风险点：</p><ul><li><strong>证书错发</strong>：某个 CA 给你的域名签了证书给别人（历史上真实发生过多次）。用 <strong>CAA 记录</strong>限定只有指定 CA 能签，用 <strong>CT 日志监控</strong>发现错发。</li><li><strong>协议与套件过时</strong>：还开着 TLS 1.0、支持 RC4，中间人可降级。</li><li><strong>证书过期</strong>：不是安全事故，但是可用性事故——而且非常常见。</li></ul><p>对应章节：<a href="/Front2Full/manual/computer-programming/web-security/tls-and-certs">TLS 与证书</a>。</p><h2 id="_3-边缘-cdn-alb-挡住的和挡不住的" tabindex="-1">③ 边缘（CDN / ALB）：挡住的和挡不住的 <a class="header-anchor" href="#_3-边缘-cdn-alb-挡住的和挡不住的" aria-label="Permalink to &quot;③ 边缘（CDN / ALB）：挡住的和挡不住的&quot;">​</a></h2><p>请求到达边缘节点。这里通常做 TLS 终止、缓存、限流、WAF。</p><p><strong>最常见的失效方式不是 WAF 规则不够好，而是攻击者根本不走边缘</strong>——他直接连你的源站 IP。你所有的边缘防护瞬间归零。</p><table tabindex="0"><thead><tr><th>风险</th><th>说明</th></tr></thead><tbody><tr><td>源站 IP 泄露</td><td>历史 DNS 记录、邮件头、证书 CT 日志、<code>/phpinfo</code> 全都能泄</td></tr><tr><td>缓存投毒</td><td>让 CDN 缓存一个被污染的响应，分发给所有人</td></tr><tr><td>限流缺失</td><td>登录接口被撞库、短信接口被刷</td></tr></tbody></table><p>对应章节：<a href="/Front2Full/manual/computer-programming/web-security/origin-exposure">源站暴露</a>、<a href="/Front2Full/manual/computer-programming/web-security/ddos-and-ratelimit">DDoS 与限流</a>、<a href="/Front2Full/manual/computer-programming/web-security/waf">WAF</a>。</p><h2 id="_4-nginx-配置比软件更容易出事" tabindex="-1">④ Nginx：配置比软件更容易出事 <a class="header-anchor" href="#_4-nginx-配置比软件更容易出事" aria-label="Permalink to &quot;④ Nginx：配置比软件更容易出事&quot;">​</a></h2><p>回源到你的 Nginx。这一层的漏洞<strong>绝大多数不是 Nginx 的锅，是配置写错了</strong>：</p><div class="language-nginx vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 少一个斜杠 —— 经典的路径穿越</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> /static </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    alias </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/var/www/static/;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 攻击者请求 /static../etc/passwd 就能跳出目录</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>还有请求走私：当 Nginx 和后端对「这个请求到哪结束」理解不一致时，攻击者可以把一个请求藏在另一个里面，绕过所有前置检查。</p><p>对应章节：<a href="/Front2Full/manual/computer-programming/web-security/nginx-baseline">Nginx 基线</a>、<a href="/Front2Full/manual/computer-programming/web-security/nginx-pitfalls">配置陷阱</a>、<a href="/Front2Full/manual/computer-programming/web-security/request-smuggling">请求走私</a>。</p><h2 id="_5-应用-输入变成指令的地方" tabindex="-1">⑤ 应用：输入变成指令的地方 <a class="header-anchor" href="#_5-应用-输入变成指令的地方" aria-label="Permalink to &quot;⑤ 应用：输入变成指令的地方&quot;">​</a></h2><p>请求进入你的代码。这一层的问题可以归成两大类：</p><p><strong>第一类：数据被当成了代码。</strong></p><table tabindex="0"><thead><tr><th>送到哪</th><th>变成什么</th><th>叫什么</th></tr></thead><tbody><tr><td>数据库</td><td>SQL 语句</td><td>SQL 注入</td></tr><tr><td>系统 shell</td><td>命令</td><td>命令注入</td></tr><tr><td>模板引擎</td><td>模板表达式</td><td>SSTI</td></tr><tr><td>浏览器</td><td>HTML / JS</td><td>XSS</td></tr><tr><td>LDAP / XML / 正则</td><td>各自的语法</td><td>各类注入</td></tr></tbody></table><p><strong>同一个根因</strong>：把不可信数据拼进了某种语法结构里。所以防御手段也同源——<strong>参数化，而不是转义</strong>。</p><p><strong>第二类：该拦的没拦。</strong></p><ul><li>没验身份（认证缺陷）</li><li>验了身份没验权限（<strong>越权 / IDOR，实战命中率最高的一类</strong>）</li><li>让服务器替攻击者发请求（SSRF）</li><li>让攻击者传了个能执行的文件（上传）</li></ul><p>对应章节：<a href="/Front2Full/manual/computer-programming/web-security/injection">注入</a>、<a href="/Front2Full/manual/computer-programming/web-security/authn">认证</a>、<a href="/Front2Full/manual/computer-programming/web-security/authz">授权</a>、<a href="/Front2Full/manual/computer-programming/web-security/ssrf">SSRF</a>、<a href="/Front2Full/manual/computer-programming/web-security/file-upload">文件上传</a>。</p><h2 id="_6-数据与外呼-横向移动的起点" tabindex="-1">⑥ 数据与外呼：横向移动的起点 <a class="header-anchor" href="#_6-数据与外呼-横向移动的起点" aria-label="Permalink to &quot;⑥ 数据与外呼：横向移动的起点&quot;">​</a></h2><p>应用查数据库、调第三方 API。攻破应用之后，攻击者关心的是<strong>还能摸到什么</strong>：</p><ul><li>数据库账号是不是超级用户？能不能读别的库？</li><li>服务器上有没有云厂商的元数据服务（<code>169.254.169.254</code>）？拿到临时凭据就能横向到整个云账号。</li><li>环境变量里有没有其它系统的密钥？</li></ul><p>这就是<a href="/Front2Full/manual/computer-programming/web-security/defense-in-depth">最小权限</a>存在的意义：<strong>假设应用一定会被攻破，那时它手上的权限决定了损失范围</strong>。</p><h2 id="回程-响应也是攻击面" tabindex="-1">回程：响应也是攻击面 <a class="header-anchor" href="#回程-响应也是攻击面" aria-label="Permalink to &quot;回程：响应也是攻击面&quot;">​</a></h2><p>请求打完了，响应回来的路上同样有风险，而且更容易被忽略：</p><table tabindex="0"><thead><tr><th>响应侧问题</th><th>后果</th></tr></thead><tbody><tr><td>缺 <code>Content-Security-Policy</code></td><td>XSS 无成本利用</td></tr><tr><td>缺 <code>X-Frame-Options</code> / <code>frame-ancestors</code></td><td>点击劫持</td></tr><tr><td>Cookie 缺 <code>HttpOnly</code> / <code>Secure</code> / <code>SameSite</code></td><td>会话被盗、CSRF</td></tr><tr><td>错误页把堆栈吐出来</td><td>泄露路径、版本、SQL 结构</td></tr><tr><td><code>Server: nginx/1.18.0</code></td><td>直接告诉扫描器该用哪个 exp</td></tr></tbody></table><p>对应章节：<a href="/Front2Full/manual/computer-programming/web-security/security-headers">安全响应头</a>、<a href="/Front2Full/manual/computer-programming/web-security/csp">CSP</a>。</p><h2 id="用一条命令看看你自己的站" tabindex="-1">用一条命令看看你自己的站 <a class="header-anchor" href="#用一条命令看看你自己的站" aria-label="Permalink to &quot;用一条命令看看你自己的站&quot;">​</a></h2><p>在读后面的章节前，先对自己的站跑一遍，看看暴露了什么：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sSI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://你的域名/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -iE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;server|x-powered-by|strict-transport|content-security|x-frame|x-content-type|referrer-policy|permissions-policy&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>理想结果是：<strong>看不到 <code>Server</code> 的具体版本、看不到 <code>X-Powered-By</code>，而后面那几个安全头都在</strong>。如果输出寥寥无几，那这个专栏对你就很值。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>攻击面远不止「表单输入」，它沿着请求路径分布在六站上。</li><li><strong>越靠前的层被打穿，后面的防御越是白做</strong>——所以专栏从域名开始，不从 XSS 开始。</li><li>应用层的问题可归成两类：数据被当成代码、该拦的没拦。</li><li>响应侧同样是攻击面，而且是投入产出比最高的一块（加几个头就能挡掉一批攻击）。</li></ul><p>下一部分从最前面那一站开始。👉 <a href="/Front2Full/manual/computer-programming/web-security/registrar-security">注册商与域名账号安全</a></p>`,47)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
